const AGENCY={name_en:'Direct Business KSA',name_ar:'دايركت أعمال',vat:'',iban:'',bank:'', /* D4+correctness fix 2026-08-24: the old literals here were the OUTDATED VAT number and an IBAN matching none of the company's registered accounts, committed to this public repo. Values now hydrate at runtime from the company_identity registry (see js/66). */iataWakeel:'71238285',iata:'71238285',legalEn:'AL MOSAFER AL MOBASHER TRAVEL & TOURISM',tradeName:'Direct Travel / DirectKSA',address:'Huda District, Jeddah St, Bldg 6409, PO Box 3743, Riyadh 12321, Saudi Arabia',website:'www.directksa.com',phone:'+966 508 434 126',amadeusOffice:'RUHS2234B',amadeusWS:'WSMSMTBS',accreditations:'IATA PAX 71238285 (2024/25/26), Amadeus production, PCI-DSS, Bank Guarantee 750K SAR, DUNS',awards:'World Travel Award x3 (2023-25), Great Place to Work x3, ICEF, English UK, British Council',cr:'1010611219',unifiedNo:'7007824068',capital:'',ceo:'Mohammed Sulaiman Aldhali',duns:'561806614',zakatId:'3114792808',tradeLicense:'73103226',amadeusPin:'9051063',org:'NMC-SAUDI'};
