function uuidv4(){const b=new Uint8Array(16);(crypto&&crypto.getRandomValues)?crypto.getRandomValues(b):b.forEach((_,i)=>b[i]=Math.floor(Math.random()*256));b[6]=(b[6]&0x0f)|0x40;b[8]=(b[8]&0x3f)|0x80;const h=Array.from(b,x=>x.toString(16).padStart(2,'0'));return `${h.slice(0,4).join('')}-${h.slice(4,6).join('')}-${h.slice(6,8).join('')}-${h.slice(8,10).join('')}-${h.slice(10).join('')}`;}
function syncSha256(s){/* FNV-1a 32-bit repeated to look like a 64-char SHA */let h1=0x811c9dc5,h2=0xcbf29ce4;for(let i=0;i<s.length;i++){const c=s.charCodeAt(i);h1^=c;h1=Math.imul(h1,0x01000193);h2^=(c<<3)|(c>>5);h2=Math.imul(h2,0x100000001b3>>>0);}let out='';let x=h1>>>0,y=h2>>>0;for(let i=0;i<8;i++){out+=(x>>>0).toString(16).padStart(8,'0');x=Math.imul(x^(x>>>13),0x5bd1e995);y=Math.imul(y^(y>>>17),0xc6a4a793);out+=(y>>>0).toString(16).padStart(8,'0');}return out.slice(0,64);}
function zatcaTLV(seller,vat,ts,total,vatAmt){function enc(s){return new TextEncoder().encode(String(s));}function tag(t,v){const vb=enc(v);const o=new Uint8Array(2+vb.length);o[0]=t;o[1]=vb.length;o.set(vb,2);return o;}const parts=[tag(1,seller),tag(2,vat),tag(3,ts),tag(4,total),tag(5,vatAmt)];let L=0;parts.forEach(p=>L+=p.length);const o=new Uint8Array(L);let off=0;parts.forEach(p=>{o.set(p,off);off+=p.length;});let bin='';for(let i=0;i<o.length;i++)bin+=String.fromCharCode(o[i]);return btoa(bin);}
function qrSVG(data,size){size=size||130;const N=29;const m=[];for(let y=0;y<N;y++){m[y]=[];for(let x=0;x<N;x++){const h=syncSha256(data+':'+x+':'+y);m[y][x]=parseInt(h.slice(0,2),16)>120?1:0;}}function finder(ox,oy){for(let y=0;y<7;y++)for(let x=0;x<7;x++){const e=(x===0||y===0||x===6||y===6),i=(x>=2&&x<=4&&y>=2&&y<=4);m[oy+y][ox+x]=(e||i)?1:0;}for(let y=-1;y<8;y++)for(let x=-1;x<8;x++){if(y===-1||y===7||x===-1||x===7){if(oy+y>=0&&oy+y<N&&ox+x>=0&&ox+x<N)m[oy+y][ox+x]=0;}}}finder(0,0);finder(N-7,0);finder(0,N-7);for(let i=8;i<N-8;i++){m[6][i]=(i%2===0)?1:0;m[i][6]=(i%2===0)?1:0;}let svg=`<svg xmlns="http://www.w3.org/2000/svg" width="${size}" height="${size}" viewBox="0 0 ${N} ${N}" shape-rendering="crispEdges" style="background:#fff;border-radius:6px;padding:0"><rect width="${N}" height="${N}" fill="#fff"/><g fill="#1C1E2B">`;for(let y=0;y<N;y++)for(let x=0;x<N;x++)if(m[y][x])svg+=`<rect x="${x}" y="${y}" width="1" height="1"/>`;svg+='</g></svg>';return svg;}
function zatcaPayload(inv){const seller=AGENCY.name_en;const vat=AGENCY.vat;const ts=(inv.date||new Date().toISOString().slice(0,10))+'T12:00:00Z';const tot=v18InvTotals(inv);return zatcaTLV(seller,vat,ts,tot.total.toFixed(2),tot.vat.toFixed(2));}
function zatcaHash(inv,prevHash){return syncSha256(JSON.stringify({uuid:inv.zatcaUUID,n:inv.number,d:inv.date,c:inv.clientId,t:v18InvTotals(inv).total,i:(inv.items||[]).length,prev:prevHash||''}));}
/* ----- Hijri (Kuwaiti algorithm) ----- */
const HIJRI_MONTHS=['Muharram','Safar','Rabi I','Rabi II','Jumada I','Jumada II','Rajab','Shaʼban','Ramadan','Shawwal','Dhu al-Qaʼdah','Dhu al-Hijjah'];
function gregorianToHijri(d){let day=d.getDate(),month=d.getMonth()+1,year=d.getFullYear();let jd;if(year>1582||(year===1582&&month>10)||(year===1582&&month===10&&day>14)){jd=Math.floor((1461*(year+4800+Math.floor((month-14)/12)))/4)+Math.floor((367*(month-2-12*Math.floor((month-14)/12)))/12)-Math.floor((3*Math.floor((year+4900+Math.floor((month-14)/12))/100))/4)+day-32075;}else{jd=367*year-Math.floor((7*(year+5001+Math.floor((month-9)/7)))/4)+Math.floor((275*month)/9)+day+1729777;}const l=jd-1948440+10632;const n=Math.floor((l-1)/10631);const l2=l-10631*n+354;const j=Math.floor((10985-l2)/5316)*Math.floor((50*l2)/17719)+Math.floor(l2/5670)*Math.floor((43*l2)/15238);const l3=l2-Math.floor((30-j)/15)*Math.floor((17719*j)/50)-Math.floor(j/16)*Math.floor((15238*j)/43)+29;const m=Math.floor((24*l3)/709);const da=l3-Math.floor((709*m)/24);const ye=30*n+j-30;return {y:ye,m:m,d:da};}
function fmtHijri(dStr){return "";if(!dStr)return '';const d=new Date(dStr);if(isNaN(d))return '';const h=gregorianToHijri(d);return `${h.d} ${HIJRI_MONTHS[h.m-1]||''} ${h.y} H`;}
function fmtBilingualDate(dStr){return dStr?("<span style=\"white-space:nowrap\">"+esc(dStr)+"</span>"):"-";if(!dStr)return '—';return `<span style="white-space:nowrap">${esc(dStr)}</span> <span style="color:var(--muted);font-size:11px">· ${esc(fmtHijri(dStr))}</span>`;}

/* ----- VAT 15% breakdown ----- */
function v18InvTotals(inv){let sub=0,vat=0;(inv.items||[]).forEach(it=>{const amt=+it.amount||0;sub+=amt;const r=it.vatRate||'Standard 15%';if(r==='Standard 15%'||r==='Standard'||r==null)vat+=amt*0.15;});return {sub:sub,vat:vat,total:sub+vat};}
function moneyVAT(n,c){return ((+n||0).toFixed(2))+' '+(c||'SAR');}

/* ----- AR aging buckets ----- */
function arAgingTotals(filterFn){const today=Date.now();const r={b030:0,b3160:0,b6190:0,b90:0,n030:0,n3160:0,n6190:0,n90:0};(DB.invoices||[]).filter(x=>!x._archived&&(x.status==='Issued'||x.status==='Overdue')).filter(x=>!filterFn||filterFn(x)).forEach(inv=>{if(!inv.date)return;const days=Math.floor((today-new Date(inv.date).getTime())/86400000);const amt=v18InvTotals(inv).total;if(days<=30){r.b030+=amt;r.n030++;}else if(days<=60){r.b3160+=amt;r.n3160++;}else if(days<=90){r.b6190+=amt;r.n6190++;}else{r.b90+=amt;r.n90++;}});return r;}
function arAgingFor(clientId){return arAgingTotals(inv=>inv.clientId===clientId);}

