/* ----- Audit log + activity feed ----- */
/* 2026-08-17 audit: this stamped every entry with the literal name 'Abdelrahman', so the log
   said he did everything no matter who was actually signed in. js/53 (v77) wraps this function
   at runtime to fix that in normal use, but the wrap only works if it runs — fixed here too so
   the base function is honest on its own and the check-structure tripwire, which was widened
   this session to scan js/core/ for the first time, stops flagging it. */
function logAudit(entity,entityId,action,detail){DB.audit=DB.audit||[];DB.audit.unshift({id:'a_'+Date.now().toString(36)+Math.random().toString(36).slice(2,5),ts:Date.now(),user:(window.__userName||'Team'),entity:entity,entityId:entityId,action:action,detail:detail||''});if(DB.audit.length>800)DB.audit=DB.audit.slice(0,800);}
function activityFor(entity,entityId){return (DB.audit||[]).filter(a=>a.entity===entity&&a.entityId===entityId);}

/* ----- Soft delete / restore ----- */
function softDeleteEntity(entity,id){const arr=DB[entity]||[];const it=arr.find(x=>x.id===id);if(it){it._archived=true;it._archivedAt=Date.now();logAudit(entity,id,'archive');save();render();}}
function restoreEntity(entity,id){const it=(DB[entity]||[]).find(x=>x.id===id);if(it){delete it._archived;delete it._archivedAt;logAudit(entity,id,'restore');save();render();}}
function activeRows(arr){return (arr||[]).filter(x=>!x._archived);}

/* ----- Smart inferences ----- */
function smartInferences(leadId){const out=[];const bks=bookingsFor(leadId).filter(b=>!b._archived);if(bks.length>=3){const by={};bks.forEach(b=>(b.tickets||[]).forEach(t=>{const a=t.airline||'?';by[a]=(by[a]||0)+1;}));const top=Object.entries(by).sort((a,b)=>b[1]-a[1])[0];if(top&&top[1]>=3){const lead=getLead(leadId);const has=(lead&&lead.airlineDeals||[]).some(d=>d.airline===top[0]);if(!has)out.push({k:'addPreferred',m:`Client booked ${top[0]} ${top[1]}× recently — add to preferred-airline panel?`});}}const lateBks=bks.filter(b=>!b.invoiceId&&onum(b.totalSale)>0);if(lateBks.length>=2)out.push({k:'invoice',m:`${lateBks.length} bookings have no invoice — generate one for each?`});const ssrOk=bks.slice(0,5).filter(b=>(b.ssr||[]).length>0).length;if(bks.length>=3&&ssrOk===0)out.push({k:'ssr',m:'No recent bookings have SSRs — consider asking pax for meal/seat prefs.'});return out;}

/* ----- Anomaly detection ----- */
function invoiceAnomaly(inv){const out=[];const linkedBks=[...new Set((inv.items||[]).map(it=>it.bookingId).filter(Boolean))].map(getBooking).filter(Boolean);const bkSum=linkedBks.reduce((s,b)=>s+onum(b.totalSale),0);const invTot=v18InvTotals(inv).total;if(linkedBks.length&&Math.abs(invTot-bkSum*1.15)>5&&Math.abs(invTot-bkSum)>5){out.push(`Invoice total ${moneyVAT(invTot)} doesn't match sum of linked bookings (${moneyVAT(bkSum)} pre-VAT / ${moneyVAT(bkSum*1.15)} inc.)`);}if(inv.status==='Issued'&&inv.date){const days=Math.floor((Date.now()-new Date(inv.date).getTime())/86400000);if(days>30)out.push('Invoice is '+days+' days old but still marked "Issued" — should be "Overdue"?');}if(!inv.zatcaUUID&&inv.status!=='Draft')out.push('ZATCA UUID missing — invoice not Phase-2 compliant.');return out;}
function bookingAnomaly(b){const out=[];if(b.totalSale&&b.totalCost&&onum(b.totalSale)<onum(b.totalCost))out.push('Sale below cost — negative margin.');if(b.totalSale&&!b.invoiceId&&b.status==='Ticketed')out.push('Ticketed but no invoice attached.');if((b.tickets||[]).length===0&&b.status==='Ticketed')out.push('Status is Ticketed but no tickets recorded.');return out;}

/* ----- Bundle templates ----- */
function saveBundleTemplate(optIdx){const o=curOffer();if(!o||!o.options[optIdx])return;const name=prompt('Save as bundle template — name?','Bundle '+new Date().toISOString().slice(0,10));if(!name)return;const opt=o.options[optIdx];DB.bundleTemplates=DB.bundleTemplates||[];const tpl={id:'tpl_'+Date.now().toString(36),name:name,items:JSON.parse(JSON.stringify(opt.items||[])),freebies:JSON.parse(JSON.stringify(opt.freebies||[])),fareFamily:opt.fareFamily||'',refundable:opt.refundable||'',baggage:opt.baggage||'',tiers:opt.tiers||[],upsells:opt.upsells||[],createdAt:Date.now()};DB.bundleTemplates.push(tpl);logAudit('offer',o.id,'save-bundle-template',name);save();alert('Saved template: '+name);offerEditor(document.getElementById('view'),o.id);}
function applyBundleTemplate(tplId,optIdx){const o=curOffer();if(!o)return;const tpl=(DB.bundleTemplates||[]).find(t=>t.id===tplId);if(!tpl||!o.options[optIdx])return;const opt=o.options[optIdx];opt.items=JSON.parse(JSON.stringify(tpl.items||[]));opt.freebies=JSON.parse(JSON.stringify(tpl.freebies||[]));opt.fareFamily=tpl.fareFamily||opt.fareFamily;opt.refundable=tpl.refundable||opt.refundable;opt.baggage=tpl.baggage||opt.baggage;opt.tiers=JSON.parse(JSON.stringify(tpl.tiers||[]));opt.upsells=JSON.parse(JSON.stringify(tpl.upsells||[]));opt._tplApplied=tpl.name;logAudit('offer',o.id,'apply-bundle-template',tpl.name);save();offerEditor(document.getElementById('view'),o.id);}
function deleteBundleTemplate(tplId){if(!confirm('Delete this bundle template?'))return;DB.bundleTemplates=(DB.bundleTemplates||[]).filter(t=>t.id!==tplId);save();render();}
