/* ----- Override ingestModal with confidence + templates + dedupe ----- */
function recognizeTemplate(fn){const s=String(fn).toLowerCase();if(/saudia|sv|065-/.test(s))return {name:'Saudia e-ticket template v3',lang:s.includes('ar')?'AR + EN':'EN'};if(/amadeus|iur|invoice/.test(s))return {name:'Amadeus IUR invoice template',lang:'EN'};if(/sabre|red360/.test(s))return {name:'Sabre Red 360 itinerary',lang:'EN'};if(/duffel|ndc/.test(s))return {name:'Duffel NDC order confirmation',lang:'EN'};if(/booking|expedia|trip\.com|agoda/.test(s))return {name:'OTA voucher (Booking/Expedia/Trip)',lang:'EN'};if(/zatca|fatoora|simplified/.test(s))return {name:'ZATCA simplified tax invoice',lang:'AR + EN'};if(/.pdf$|.png$|.jpg$|.eml$|.msg$/.test(s))return {name:'Generic document (template-detect fallback)',lang:'EN'};return null;}
function confidencePill(p){const cls=p>=90?'conf-hi':p>=70?'conf-md':'conf-lo';return `<span class="confpill ${cls}">${p}%</span>`;}
function confInputLabel(label,p){return `<label>${esc(label)} ${confidencePill(p)}</label>`;}
function findDuplicate(kind,fields){if(kind==='invoice'){return (DB.invoices||[]).find(i=>!i._archived&&(i.number===fields.number||(i.zatcaUUID&&i.zatcaUUID===fields.zatcaUUID)));}if(kind==='booking'){return (DB.bookings||[]).find(b=>!b._archived&&(b.ref===fields.ref||(b.pnr&&fields.pnr&&b.pnr===fields.pnr)));}return null;}
