/* ----- v20 sync helpers ----- */
function syncBadge(ent){if(!ent||!ent.sourceSystem)return '';const sys=SOURCE_SYSTEMS[ent.sourceSystem];if(!sys)return '';return `<span class="v20-source-tag" title="Source of truth: ${esc(sys.label)} · ${esc(sys.role)}"><span class="ic">${sys.ic}</span>Synced from ${esc(sys.label)} · ${esc(fmtRel(ent.lastSyncedAt))}</span>`;}
function healthPill(ent,withLog){if(!ent||!ent.syncHealth)return '';const h=SYNC_HEALTH[ent.syncHealth]||SYNC_HEALTH.synced;const click=withLog!==false?`onclick="event.stopPropagation();openSyncLog('${ent.id||''}','${ent.sourceSystem||'internal'}')"`:'';return `<span class="v20-sync-pill" style="background:${h.bg};color:${h.c};border-color:${h.c}33" ${click}><span class="dot"></span>${h.ic} ${h.l} · ${esc(fmtRel(ent.lastSyncedAt))}</span>`;}
function openSyncLog(entId,sys){const all=[];(DB.invoices||[]).forEach(i=>{if(i.id===entId)(i.syncLog||[]).forEach(l=>all.push(Object.assign({entity:'invoice',entityId:i.id},l)));});(DB.bookings||[]).forEach(b=>{if(b.id===entId)(b.syncLog||[]).forEach(l=>all.push(Object.assign({entity:'booking',entityId:b.id},l)));});const evs=(DB.syncEvents||[]).filter(e=>e.entityId===entId||e.source===sys).slice(0,30);openModal('Sync log',`<div class="v20-sync-log">${(all.concat(evs)).sort((a,b)=>b.ts-a.ts).slice(0,40).map(l=>`<div class="row"><span class="ts">${fmtRel(l.ts)}</span><span class="src">${esc((SOURCE_SYSTEMS[l.source]||{label:l.source||'?'}).label)}</span><span class="dir">${l.dir==='in'?'⬇ inbound':l.dir==='out'?'⬆ outbound':'⇅'}</span><span><span class="tag" style="background:${(SYNC_HEALTH[l.result]||{bg:'#eef0f5'}).bg};color:${(SYNC_HEALTH[l.result]||{c:'#5b6178'}).c}">${esc(l.result||'')}</span> ${esc(l.note||'')}</span></div>`).join('')||'<div class="empty">No sync events.</div>'}</div>`,()=>{});}
function v20DeepLinkFooter(ent,extraLinks){if(!ent||!ent.sourceSystem)return '';const sys=SOURCE_SYSTEMS[ent.sourceSystem];const links=[];if(sys&&sys.deepLink)links.push({label:'View in '+sys.label,url:ent.deepLinkToSource||deepLink(ent.sourceSystem,ent.sourceRecordId)});if(extraLinks)extraLinks.forEach(l=>links.push(l));if(!links.length)return '';return `<div class="v20-deeplink-foot"><span class="lbl">Source systems</span>${links.map(l=>`<a href="${esc(l.url)}" target="_blank" rel="noopener" onclick="event.stopPropagation()">${esc(l.label)}</a>`).join('')}<span style="color:var(--muted);font-size:11px;margin-left:auto">Source-system actions execute outside the dashboard.</span></div>`;}
/* confirm modal that names the source system */
(function buildConfirm(){const c=document.createElement('div');c.className='v20-confirm';c.id='v20confirm';document.body.appendChild(c);c.addEventListener('click',e=>{if(e.target===c)c.classList.remove('show');});})();
function performAction(opts){const sys=SOURCE_SYSTEMS[opts.system]||SOURCE_SYSTEMS.internal;const c=document.getElementById('v20confirm');c.innerHTML=`<div class="cb"><div class="ch"><h3>${esc(opts.title||'Confirm action')}</h3><div class="sys" style="background:${sys.color}1a;color:${sys.color}">${sys.ic} Executes on ${esc(sys.label)}</div></div><div class="cm">${opts.body||''}<div class="pre">${esc(opts.detail||'')}</div><div style="font-size:11.5px;color:var(--muted);margin-top:6px">This is a mock. In the live phase the dashboard issues an <b>idempotent</b> request to ${esc(sys.label)} and waits for the source-system response. The local row enters a <b>Pending</b> state until the source confirms.</div></div><div class="cf"><button class="btn ghost" onclick="document.getElementById('v20confirm').classList.remove('show')">Cancel</button><button class="btn v20-ext" id="v20confirmGo">${esc(opts.cta||('Run on '+sys.label))}</button></div></div>`;c.classList.add('show');document.getElementById('v20confirmGo').onclick=()=>{c.classList.remove('show');runOptimistic(opts);};}
function runOptimistic(opts){const ent=opts.entity;if(ent){ent.syncHealth='pending';ent.lastSyncedAt=Date.now();(ent.syncLog=ent.syncLog||[]).push({ts:Date.now(),dir:'out',result:'pending',source:opts.system,note:opts.title||'action'});silentSave(save);render();toast('Pending sync to '+(SOURCE_SYSTEMS[opts.system]||{label:opts.system}).label);}setTimeout(()=>{if(opts.run)opts.run();if(ent){ent.syncHealth='synced';ent.lastSyncedAt=Date.now();(ent.syncLog=ent.syncLog||[]).push({ts:Date.now(),dir:'in',result:'synced',source:opts.system,note:'Source confirmed'});(DB.syncEvents=DB.syncEvents||[]).unshift({id:'se_'+Date.now().toString(36),ts:Date.now(),source:opts.system,dir:'in',result:'success',entity:opts.entityKind||'',entityId:ent.id||'',note:opts.title||''});silentSave(save);render();toast((opts.successMsg||'Synced ✓'));}},1200);}
/* ----- v20 override invoiceDetail — sync pill, system-labeled CTAs, footer, conflict banner ----- */
const _v19InvoiceDetail=invoiceDetail;
invoiceDetail=function(v,id){_v19InvoiceDetail(v,id);setTimeout(()=>{const inv=getInvoice(id);if(!inv)return;const view=document.getElementById('view');if(!view)return;const head=view.querySelector('.detail-head');if(head&&!head.querySelector('.v20HdrSync')){const wrap=document.createElement('div');wrap.className='v20HdrSync';wrap.style.cssText='display:flex;gap:6px;flex-wrap:wrap;align-items:center;margin-top:6px;width:100%';wrap.innerHTML=healthPill(inv)+' '+syncBadge(inv);const txtCol=head.querySelector('div[style*="flex:1"]');if(txtCol)txtCol.appendChild(wrap);}
  // Replace generic "Mark paid" button with system-labeled version
  const oldPay=view.querySelector('.v19InvCTA');if(oldPay&&inv.status!=='Paid'){oldPay.innerHTML=`<button class="btn v20-ext sm" onclick="v20MarkPaid('${id}')">💰 Mark paid <span class="v20-action-sys">· Direct Payment</span></button> <button class="btn sm" onclick="v20Refund('${id}')">↩ Refund <span style="color:var(--muted);font-size:10.5px">· Direct Payment</span></button>`;}
  // Conflict banner
  if(inv.syncHealth==='conflict'&&inv.syncConflict&&!view.querySelector('.v20ConflictBanner')){const cb=document.createElement('div');cb.className='v20ConflictBanner anomaly';cb.style.cssText='background:#EEEBFE;border-color:#D6CFFC;color:#5b46d6';cb.innerHTML=`<span class="ic">⚠</span><div style="flex:1"><b>Conflict with source system (Direct Payment).</b> Dashboard cache differs from Direct Payment's record. <button class="btn sm" style="margin-left:8px" onclick="openConflict('invoice','${id}')">Review & resolve</button></div>`;const anchor=view.querySelector('.zatca-panel');if(anchor)anchor.parentNode.insertBefore(cb,anchor);}
  // Deep-link footer
  if(!view.querySelector('.v20-deeplink-foot')){const links=[{label:'Open ZATCA Fatoora ↗',url:deepLink('zatca',inv.zatcaUUID||id)}];const foot=document.createElement('div');foot.innerHTML=v20DeepLinkFooter(inv,links);if(foot.firstChild)view.appendChild(foot.firstChild);}
},40);};

/* ----- v20 override bookingDetail — sync pill, system-labeled CTAs ----- */
const _v19BookingDetail=bookingDetail;
bookingDetail=function(v,id){_v19BookingDetail(v,id);setTimeout(()=>{const b=getBooking(id);if(!b)return;const view=document.getElementById('view');if(!view)return;const head=view.querySelector('.detail-head');if(head&&!head.querySelector('.v20HdrSync')){const wrap=document.createElement('div');wrap.className='v20HdrSync';wrap.style.cssText='display:flex;gap:6px;flex-wrap:wrap;align-items:center;margin-top:6px;width:100%';wrap.innerHTML=healthPill(b)+' '+syncBadge(b);const txtCol=head.querySelector('div[style*="flex:1"]');if(txtCol)txtCol.appendChild(wrap);}
  // Re-label v19 booking CTAs with execution system
  const oldCTA=view.querySelector('.v19BkCTA');if(oldCTA){const sys=SOURCE_SYSTEMS[b.sourceSystem]||SOURCE_SYSTEMS.internal;const inv=(DB.invoices||[]).find(x=>x.id===b.invoiceId);oldCTA.innerHTML=`<button class="btn v20-ext sm" onclick="v20IssueTicket('${id}')">🎫 Issue ticket <span class="v20-action-sys">· ${esc(sys.label)}</span></button>`+(inv?`<button class="btn sm" onclick="openInvoice='${inv.id}';current='invoices';render()">🧾 ${esc(inv.number)}</button>`:`<button class="btn sm" onclick="v20InvoiceFromBooking('${id}')">🧾 Generate invoice <span style="color:var(--muted);font-size:10.5px">· Direct Payment</span></button>`)+`<button class="btn sm" onclick="v20VoidBooking('${id}')">↩ Void <span style="color:var(--muted);font-size:10.5px">· ${esc(sys.label)}</span></button>`;}
  // Conflict banner
  if(b.syncHealth==='conflict'&&b.syncConflict&&!view.querySelector('.v20ConflictBanner')){const cb=document.createElement('div');cb.className='v20ConflictBanner anomaly';cb.style.cssText='background:#EEEBFE;border-color:#D6CFFC;color:#5b46d6';cb.innerHTML=`<span class="ic">⚠</span><div style="flex:1"><b>Conflict with ${esc((SOURCE_SYSTEMS[b.sourceSystem]||{label:'source'}).label)}.</b> Dashboard cache differs. <button class="btn sm" style="margin-left:8px" onclick="openConflict('booking','${id}')">Review & resolve</button></div>`;const dh=view.querySelector('.detail-head');if(dh)dh.parentNode.insertBefore(cb,dh.nextSibling);}
  // Deep-link footer (with ticket links)
  if(!view.querySelector('.v20-deeplink-foot')){const links=[];if(b.invoiceId){const inv=getInvoice(b.invoiceId);if(inv)links.push({label:'Open invoice in Direct Payment ↗',url:deepLink('direct_payment',inv.sourceRecordId||inv.id)});}const foot=document.createElement('div');foot.innerHTML=v20DeepLinkFooter(b,links);if(foot.firstChild)view.appendChild(foot.firstChild);}
},40);};

/* ----- v20 system-labeled action handlers (wrap with confirm + optimistic) ----- */
function v20MarkPaid(id){const inv=getInvoice(id);if(!inv)return;const amt=v18InvTotals(inv).total;performAction({system:'direct_payment',entity:inv,entityKind:'invoice',title:'Mark invoice paid',body:`Mark invoice <b>${esc(inv.number)}</b> for <b>${esc(leadName(inv.clientId))}</b> as paid.`,detail:'Total to settle: '+amt.toFixed(2)+' SAR · Method will be selected on Direct Payment',cta:'💰 Confirm payment',successMsg:'Marked paid · '+moneyShort(amt)+' SAR',run:()=>{if(typeof markInvoicePaid==='function')markInvoicePaid(id);else{inv.status='Paid';inv.payments=inv.payments||[];inv.payments.push({date:new Date().toISOString().slice(0,10),amount:amt,method:'Direct Payment',ref:'v20-'+Date.now().toString(36).toUpperCase()});}}});}
function v20Refund(id){const inv=getInvoice(id);if(!inv)return;performAction({system:'direct_payment',entity:inv,entityKind:'invoice',title:'Refund invoice',body:`Issue refund for <b>${esc(inv.number)}</b>.`,detail:'Refund amount: '+v18InvTotals(inv).total.toFixed(2)+' SAR · Reversal will be raised on Direct Payment',cta:'↩ Confirm refund',successMsg:'Refund initiated',run:()=>{(inv.payments=inv.payments||[]).push({date:new Date().toISOString().slice(0,10),amount:-v18InvTotals(inv).total,method:'Direct Payment refund',ref:'rfd-'+Date.now().toString(36).toUpperCase()});inv.status='Refunded';logAudit('invoice',id,'refund','via Direct Payment');}});}
function v20IssueTicket(id){const b=getBooking(id);if(!b)return;const sys=b.sourceSystem||'amadeus';performAction({system:sys,entity:b,entityKind:'booking',title:'Issue ticket',body:`Issue e-ticket(s) on <b>${esc((SOURCE_SYSTEMS[sys]||{label:sys}).label)}</b> against PNR <code>${esc(b.pnr||'—')}</code>.`,detail:'Booking '+b.ref+' · '+bkAirlines(b).join(', ')+' · pax ['+(b.tickets||[]).map(t=>t.pax).join(', ')+']',cta:'🎫 Issue on '+(SOURCE_SYSTEMS[sys]||{label:sys}).label,successMsg:'Ticket issuance queued on '+(SOURCE_SYSTEMS[sys]||{label:sys}).label,run:()=>{if(typeof ticketFromBooking==='function')ticketFromBooking(id);b.status='Ticketed';logAudit('booking',id,'issue-ticket','via '+sys);}});}
function v20VoidBooking(id){const b=getBooking(id);if(!b)return;const sys=b.sourceSystem||'amadeus';performAction({system:sys,entity:b,entityKind:'booking',title:'Void booking',body:`Void booking <b>${esc(b.ref)}</b> on ${esc((SOURCE_SYSTEMS[sys]||{label:sys}).label)}.`,detail:'PNR '+(b.pnr||'—')+' will be cancelled at source. Tickets will be voided if within void window.',cta:'↩ Void at source',successMsg:'Void request sent',run:()=>{b.status='Cancelled';logAudit('booking',id,'void','via '+sys);}});}
