// Hash chain integrity check (recomputes every invoice's hash from current data, compares stored)
function v21VerifyHashChain(){const invs=(DB.invoices||[]).filter(x=>x.zatcaHash).slice();invs.sort((a,b)=>(a.date||'').localeCompare(b.date||''));let prevHash='';const issues=[];invs.forEach((i,idx)=>{const expected=zatcaHash(i,prevHash);const ok=i.zatcaHash===expected&&(i.prevHash||'')===prevHash;if(!ok)issues.push({idx,number:i.number,id:i.id,storedHash:(i.zatcaHash||'').slice(0,16),expectedHash:expected.slice(0,16),storedPrev:(i.prevHash||'').slice(0,16),expectedPrev:prevHash.slice(0,16)});prevHash=i.zatcaHash||expected;});return {checked:invs.length,issues};}
function v21HashChainBanner(){const r=v21VerifyHashChain();if(!r.issues.length)return null;const banner=document.createElement('div');banner.className='anomaly';banner.style.cssText='background:#FDECEB;border-color:#F5BFBC;color:#a4221c;padding:12px 16px;border-radius:11px;margin-bottom:14px';banner.innerHTML=`<span class="ic">⚠</span><div style="flex:1"><b>ZATCA hash-chain mismatch</b> on ${r.issues.length}/${r.checked} invoice(s) — possible tampering or migration artifact. <button class="btn sm" onclick="v21OpenHashReport()">Open report</button></div>`;return banner;}
function v21OpenHashReport(){const r=v21VerifyHashChain();const rows=r.issues.map(i=>`<tr><td>${esc(i.number)}</td><td style="font-family:ui-monospace,Consolas;font-size:11px">${esc(i.storedHash)}…</td><td style="font-family:ui-monospace,Consolas;font-size:11px">${esc(i.expectedHash)}…</td><td><span class="tag" style="background:#FDECEB;color:#a4221c">mismatch</span></td></tr>`).join('');openModal('ZATCA hash-chain integrity report',`<div>${r.checked} invoices checked · ${r.issues.length} mismatches</div>${r.issues.length?'<table style="margin-top:10px;font-size:12px"><thead><tr><th>Invoice</th><th>Stored</th><th>Expected</th><th></th></tr></thead><tbody>'+rows+'</tbody></table><div style="margin-top:10px"><button class="btn pri sm" onclick="v21RepairHashChain();closeModal()">🔧 Repair chain (recompute)</button></div>':'<div class="empty">All chains valid ✓</div>'}`,()=>{});}
function v21RepairHashChain(){const invs=(DB.invoices||[]).filter(x=>x.zatcaUUID).slice().sort((a,b)=>(a.date||'').localeCompare(b.date||''));let prevHash='';invs.forEach(i=>{i.prevHash=prevHash;i.zatcaHash=zatcaHash(i,prevHash);i.zatcaTLV=zatcaPayload(i);prevHash=i.zatcaHash;});logAudit('system','','hash-chain-repair','re-computed '+invs.length+' invoices');save();render();toast('Hash chain repaired ('+invs.length+' invoices)');}
// PII masking helper for audit log — masks middle digits of 10+ char IDs
function v21MaskPII(s){if(!s||typeof s!=='string'||s.length<7)return s;return s.slice(0,3)+'***'+s.slice(-3);}
const _v21OrigLogAudit=typeof logAudit==='function'?logAudit:null;if(_v21OrigLogAudit){logAudit=function(entity,entityId,action,detail){let d=detail;if(typeof d==='string'){d=d.replace(/\b(\d{10,15})\b/g,m=>v21MaskPII(m));d=d.replace(/([A-Z0-9]{6,})/g,m=>m.length>=10?v21MaskPII(m):m);}_v21OrigLogAudit(entity,entityId,action,d);};}
