  // STEP 4 — DRAFT invoice (not yet pushed to Direct Payment)
  const draftInv={id:'inv_rad_'+Date.now().toString(36),number:'DRAFT-'+Date.now().toString().slice(-4),clientId:lead.id,date:new Date().toISOString().slice(0,10),currency:'SAR',status:'Draft',invoiceType:'Standard',items:[{desc:'RUH-LHR-RUH (SV J) — Test Pax',bookingId:booking.id,amount:6250,vatRate:'Standard 15%'}],total:0,files:[],notes:'',zatcaUUID:'',zatcaStatus:'Draft',sourceSystem:'internal',syncHealth:'pending',_v21test:true,_v21draft:true};
  draftInv.total=v18InvTotals(draftInv).total;
