  v21Assert('4. Invoice DRAFTED (not pushed)',draftInv.status==='Draft'&&!draftInv.zatcaUUID,'draft only');
  // STEP 5 — Push draft → Direct Payment (mock sync)
  draftInv.zatcaUUID=uuidv4();draftInv.sourceSystem='direct_payment';draftInv.sourceRecordId=draftInv.number;draftInv.syncHealth='pending';draftInv.lastSyncedAt=Date.now();
  const lastInv=(DB.invoices||[]).filter(x=>x.zatcaHash&&x.id!==draftInv.id).slice(-1)[0];
  draftInv.prevHash=lastInv?lastInv.zatcaHash:'';draftInv.zatcaHash=zatcaHash(draftInv,draftInv.prevHash);draftInv.zatcaTLV=zatcaPayload(draftInv);draftInv.status='Issued';draftInv.zatcaStatus='Submitted';
