  (DB.syncEvents=DB.syncEvents||[]).unshift({id:'se_radTkt_'+Date.now().toString(36),ts:Date.now(),source:'amadeus',dir:'in',result:'success',entity:'booking',entityId:booking.id,note:'Ticket issued (mock sync inbound)'});
